// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // Bound value to avoid overflow issues
        _value = bound(_value, 0, address(c).balance);
        // Fund the contract if needed
        vm.deal(address(c), _value);

        // Try calling sendMoney and capture if it reverts
        bool success;
        (bool sent, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));
        success = sent;

        // The rule: sendMoney should not revert for any target
        assertTrue(success, "sendMoney should not revert");
    }
}

